const correctAnswers = {
  q1: ["js", "python", "ruby"],   // interpreted languages
  q2: ["c", "cpp", "rust"],       // languages with manual memory management
  q3: ["java", "cs", "kotlin"],   // JVM / CLR compiled languages
};

document.querySelectorAll(".option").forEach((option) => {
  option.addEventListener("click", () => {
    const checkbox = option.querySelector("input[type='checkbox']");
    checkbox.checked = !checkbox.checked;
    option.classList.toggle("checked", checkbox.checked);
  });
});

document.getElementById("quiz-form").addEventListener("submit", (e) => {
  e.preventDefault();

  let totalCorrect = 0;
  let totalQuestions = Object.keys(correctAnswers).length;

  Object.entries(correctAnswers).forEach(([name, correct]) => {
    const selected = [...document.querySelectorAll(`input[name="${name}"]:checked`)]
      .map((el) => el.value);

    const isCorrect =
      selected.length === correct.length &&
      correct.every((v) => selected.includes(v));

    if (isCorrect) totalCorrect++;
  });

  const toast = document.getElementById("result-toast");
  const scoreEl = document.getElementById("score");
  const messageEl = document.getElementById("result-message");

  scoreEl.textContent = `${totalCorrect} / ${totalQuestions}`;

  if (totalCorrect === totalQuestions) {
    messageEl.textContent = "Perfect score! You really know your languages. 🎉";
  } else if (totalCorrect >= 2) {
    messageEl.textContent = "Great job! You got most questions right.";
  } else if (totalCorrect === 1) {
    messageEl.textContent = "Not bad — keep brushing up on language fundamentals!";
  } else {
    messageEl.textContent = "No worries — review the answers and try again!";
  }

  toast.classList.add("visible");
  toast.scrollIntoView({ behavior: "smooth", block: "nearest" });
});
