}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Inter", sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 64px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 640px;
}

.quiz-header {
  margin-bottom: 32px;
}

.quiz-header .eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 8px;
}

.quiz-header h1 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.25;
}

.quiz-header p {
  margin-top: 8px;
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
}

.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── form-field card ── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: box-shadow .2s ease;
}

.form-field:focus-within {
  box-shadow: var(--shadow-card);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.question-number {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-light);
  padding: 2px 8px;
  border-radius: 20px;
}

.question-label {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 6px;
  line-height: 1.4;
}

.help-text {
  font-size: 13px;
  color: var(--text-help);
  margin-bottom: 16px;
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 1px;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 14px;
}

/* ── checkbox option ── */
.option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease;
  user-select: none;
}

.option:hover {
  border-color: #a5b4fc;
  background: #fafbff;
}

.option input[type="checkbox"] {
  display: none;
}

.option.checked {
  border-color: var(--border-focus);
  background: var(--accent-light);
}

.custom-checkbox {
  width: 20px;
  height: 20px;
  border-radius: 5px;
  border: 2px solid var(--border);
  background: var(--surface);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color .15s ease, background .15s ease;
}

.option.checked .custom-checkbox {
  border-color: var(--accent);
  background: var(--accent);
}

.custom-checkbox svg {
  opacity: 0;
  transform: scale(.7);
  transition: opacity .15s ease, transform .15s ease;
}

.option.checked .custom-checkbox svg {
  opacity: 1;
  transform: scale(1);
}

.option-text {
  font-size: 14.5px;
  color: var(--text-primary);
  line-height: 1.4;
}

.option.checked .option-text {
  font-weight: 500;
  color: var(--accent);
}

/* ── submit ── */
.submit-area {
  margin-top: 8px;
}

.btn-submit {
  width: 100%;
  padding: 14px 24px;
  background: var(--accent);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .15s ease, transform .1s ease, box-shadow .15s ease;
  box-shadow: 0 2px 8px rgba(99,102,241,.35);
  letter-spacing: .01em;
}

.btn-submit:hover {
  background: var(--accent-hover);
  box-shadow: 0 4px 16px rgba(99,102,241,.45);
}

.btn-submit:active {
  transform: translateY(1px);
}

/* ── result toast ── */
.result-toast {
  display: none;
  align-items: flex-start;
  gap: 14px;
  padding: 20px 22px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-card);
  margin-top: 20px;
}

.result-toast.visible {
  display: flex;
}

.result-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.result-icon svg {
  color: var(--accent);
}

.result-body h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.result-body p {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 3px;
  line-height: 1.5;
}

.score-highlight {
  color: var(--accent);
  font-weight: 700;
}
